diff --git a/tests/options.optsWithGlobals.test.js b/tests/options.optsWithGlobals.test.js
index 0f84454..19d1f43 100644
--- a/tests/options.optsWithGlobals.test.js
+++ b/tests/options.optsWithGlobals.test.js
@@ -68,6 +68,67 @@ describe('Command.optsWithGlobals()', () => {
 });

 describe('getOptionValueSourceWithGlobals', () => {
+  for (const storeAsProperties of [false, true]) {
+    describe(`with storeOptionsAsProperties(${storeAsProperties})`, () => {
+      for (const globalValue of ['global value', undefined]) {
+        test(`global value ${globalValue} with unknown source masks child source`, () => {
+          const program = new commander.Command()
+            .storeOptionsAsProperties(storeAsProperties)
+            .option('--common <value>');
+          const sub = program
+            .command('sub')
+            .storeOptionsAsProperties(storeAsProperties)
+            .option('--common <value>');
+          program.setOptionValue('common', globalValue);
+          sub.setOptionValueWithSource('common', 'child value', 'cli');
+
+          assert.equal(sub.optsWithGlobals().common, globalValue);
+          assert.equal(sub.getOptionValueSourceWithGlobals('common'), undefined);
+        });
+      }
+
+      test('unknown source masks nested child source while preserving child-only values', () => {
+        const program = new commander.Command().storeOptionsAsProperties(
+          storeAsProperties,
+        );
+        const sub = program
+          .command('sub')
+          .storeOptionsAsProperties(storeAsProperties)
+          .option('--common <value>');
+        const nested = sub
+          .command('nested')
+          .storeOptionsAsProperties(storeAsProperties)
+          .option('--common <value>')
+          .option('--local <value>');
+        sub.setOptionValue('common', 'parent value');
+        nested.setOptionValueWithSource('common', 'child value', 'cli');
+        nested.setOptionValueWithSource('local', 'local value', 'env');
+
+        assert.deepEqual(nested.optsWithGlobals(), {
+          common: 'parent value',
+          local: 'local value',
+        });
+        assert.equal(nested.getOptionValueSourceWithGlobals('common'), undefined);
+        assert.equal(nested.getOptionValueSourceWithGlobals('local'), 'env');
+        assert.equal(nested.getOptionValueSourceWithGlobals('missing'), undefined);
+      });
+    });
+  }
+
+  for (const source of ['default', 'config', 'env', 'cli', 'implied']) {
+    test(`recognized global source ${source} overrides unknown source in nested command`, () => {
+      const program = new commander.Command();
+      const sub = program.command('sub');
+      const nested = sub.command('nested');
+      program.setOptionValueWithSource('common', 'global value', source);
+      sub.setOptionValue('common', 'parent value');
+      nested.setOptionValueWithSource('common', 'child value', 'cli');
+
+      assert.equal(nested.optsWithGlobals().common, 'global value');
+      assert.equal(nested.getOptionValueSourceWithGlobals('common'), source);
+    });
+  }
+
   test('when option used with simple command then source is defined', () => {
     const program = new commander.Command();
     program.option('-g, --global');

